        if node.orelse:
            raise Unsupported("while-else")
        return Ctor("While", emit_expr(node.test), emit_stmts(node.body))

    if isinstance(node, ast.Break):
        return "Break"
    if isinstance(node, ast.Continue):
        return "Continue"
    if isinstance(node, ast.Pass):
